CREATE OR REPLACE FUNCTION public.member_waiting_add_form(p_request uuid, p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row        public.member_requests;
  v_size       bigint;
  v_mime       text;
  v_constraint text;
BEGIN
  IF public.member_is_manager('member_requests_manage') IS NOT TRUE
     OR public.has_any_action(ARRAY['member.manage']) IS NOT TRUE THEN
    RAISE EXCEPTION 'HR management access is required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.member_requests WHERE id = p_request FOR UPDATE;
  IF NOT FOUND OR v_row.created_by IS DISTINCT FROM auth.uid() OR v_row.kind IS DISTINCT FROM 'waiting'
     OR v_row.status IS DISTINCT FROM 'draft' OR v_row.detail ->> 'addedBy' IS DISTINCT FROM 'hr'
     OR coalesce(v_row.detail ->> 'signedFormHash', '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'This addition is no longer waiting for its form. Close the window and look at the list.' USING ERRCODE = '22023';
  END IF;
  IF p_path IS NULL OR p_path !~ ('^' || auth.uid()::text || '/' || p_request::text || '/[0-9a-f-]{36}\.(pdf|png|jpg|docx|doc)$') THEN
    RAISE EXCEPTION 'Attach the signed application form again' USING ERRCODE = '22023';
  END IF;
  IF to_regclass('public.file_objects') IS NULL THEN
    RAISE EXCEPTION 'Attach the signed application form again' USING ERRCODE = '22023';
  END IF;
  EXECUTE 'SELECT (o.metadata ->> ''size'')::bigint, o.metadata ->> ''mimetype'' FROM public.file_objects o
            WHERE o.bucket_id = ''member-invoices'' AND o.name = $1'
     INTO v_size, v_mime USING p_path;
  IF v_size IS NULL OR v_size < 1 OR v_size > 3145728 OR v_mime IS NULL
     OR v_mime NOT IN ('application/pdf', 'image/png', 'image/jpeg', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword') THEN
    RAISE EXCEPTION 'Attach the signed application form again' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.member_request_attachments (request_id, uploaded_by, object_path, mime_type, size_bytes, content_sha256)
  VALUES (v_row.id, auth.uid(), p_path, v_mime, v_size, v_row.detail ->> 'signedFormHash');
  BEGIN
    UPDATE public.member_requests
       SET status = 'waiting', submitted_at = now(), reviewed_by = auth.uid(), reviewed_at = now(), note = 'Added on Sales Groups'
     WHERE id = v_row.id
    RETURNING * INTO v_row;
  EXCEPTION WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint = 'member_waiting_unique_contact' THEN
      RAISE EXCEPTION 'This phone number is already on the waiting list, or waiting for review in Member services' USING ERRCODE = '22023';
    END IF;
    RAISE;
  END;
  RETURN jsonb_build_object('id', v_row.id, 'requestNo', v_row.request_no, 'status', v_row.status);
END
$function$

CREATE OR REPLACE FUNCTION public.member_waiting_attach_form(p_request uuid, p_path text, p_name text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row  public.member_requests;
  v_name text := left(btrim(coalesce(p_name, '')), 200);
  v_size bigint;
  v_mime text;
  v_at   timestamptz;
BEGIN
  IF public.member_is_manager('member_requests_manage') IS NOT TRUE
     OR public.has_any_action(ARRAY['member.manage']) IS NOT TRUE THEN
    RAISE EXCEPTION 'HR management access is required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.member_requests WHERE id = p_request FOR UPDATE;
  IF NOT FOUND OR v_row.kind IS DISTINCT FROM 'waiting'
     OR coalesce(v_row.status, '') NOT IN ('waiting', 'reserved', 'accepted') THEN
    RAISE EXCEPTION 'This applicant is no longer on the waiting list. Reload the page.' USING ERRCODE = '22023';
  END IF;
  IF v_name = '' OR coalesce(p_hash, '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;
  IF p_path IS NULL OR p_path !~ ('^' || auth.uid()::text || '/' || p_request::text || '/[0-9a-f-]{36}\.(pdf|png|jpg|docx|doc)$') THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;
  IF v_row.detail ->> 'signedFormHash' IS NOT DISTINCT FROM p_hash
     AND EXISTS (SELECT 1 FROM public.member_request_attachments a WHERE a.request_id = v_row.id AND a.content_sha256 = p_hash) THEN
    RAISE EXCEPTION 'This file is already their signed form' USING ERRCODE = '22023';
  END IF;
  IF to_regclass('public.file_objects') IS NULL THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;
  EXECUTE 'SELECT (o.metadata ->> ''size'')::bigint, o.metadata ->> ''mimetype'' FROM public.file_objects o
            WHERE o.bucket_id = ''member-invoices'' AND o.name = $1'
     INTO v_size, v_mime USING p_path;
  IF v_size IS NULL OR v_size < 1 OR v_size > 3145728 OR v_mime IS NULL
     OR v_mime NOT IN ('application/pdf', 'image/png', 'image/jpeg', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword')
     OR substring(p_path FROM '\.([a-z]+)$') IS DISTINCT FROM (CASE v_mime WHEN 'application/pdf' THEN 'pdf' WHEN 'image/png' THEN 'png' WHEN 'image/jpeg' THEN 'jpg' WHEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' THEN 'docx' WHEN 'application/msword' THEN 'doc' END) THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.member_request_attachments (request_id, uploaded_by, object_path, mime_type, size_bytes, content_sha256)
  VALUES (v_row.id, auth.uid(), p_path, v_mime, v_size, p_hash)
  RETURNING created_at INTO v_at;
  UPDATE public.member_requests
     SET detail = detail || jsonb_build_object('signedFormName', v_name, 'signedFormHash', p_hash)
   WHERE id = v_row.id;
  INSERT INTO public.member_request_events (request_id, actor_id, from_status, to_status, note)
  VALUES (v_row.id, auth.uid(), v_row.status, v_row.status, 'Signed form uploaded · ' || v_name);
  RETURN jsonb_build_object(
    'name', v_name,
    'type', v_mime,
    'at', v_at,
    'by', coalesce(
      (SELECT s.employee_name FROM public.hr_staff_costs s WHERE s.user_id = auth.uid() ORDER BY s.status = 'active' DESC LIMIT 1),
      (SELECT CASE u.role::text WHEN 'hr' THEN 'HR' WHEN 'principal' THEN 'Principal' WHEN 'finance' THEN 'Finance' ELSE initcap(replace(u.role::text, '_', ' ')) END
         FROM public.users u WHERE u.id = auth.uid())
    )
  );
END
$function$
